/* Original lightweight personalities, conversation state and domestic cat. */
static const char*eventpath="okno_events.csv";static int eventsWritten=0,lastWindowEvent=-1;static float eventValue=0;
static char dialogue[640],personName[96];
static const char*npc_first[]={"Александр","Лидия","Семён","Рита","Нина","Марк","Вера","Борис","Юля","Денис","Зоя","Тимур","Саша","Павел","Лена","Кирилл"};
static const char*npc_last[]={"Сосновых","Речных","Лесных"};
static int persona(int n){return (int)(hash32(g.worldSeed+n*9137+77)%8);}
static int friendliness(int n){return 20+(int)(hash32(n*515+g.worldSeed)%75);}
static int noisiness(int n){return 10+(int)(hash32(n*181+g.worldSeed)%90);}
static int diet(int n){return (int)(hash32(n*383+g.worldSeed)%5);}
static const char*npc_name(int n){static const char*m[]={"Сергей","Виктор","Олег","Андрей","Павел","Юрий","Михаил","Семён","Руслан","Артур","Алексей","Борис"};static const char*w[]={"Наталья","Ирина","Людмила","Татьяна","Ольга","Валентина","Елена","Светлана","Рада","Милана","Галина","Зоя"};static const char*s[]={"Лесных","Речных","Сосновых","Долгих","Черных","Белых","Коротких","Седых"};int code=(n+(g.worldSeed%12))%12;SN(personName,sizeof(personName),"%s %s",npc_woman(n)?w[code]:m[code],s[(n/12+g.worldSeed/12)%8]);return personName;}
static const char*dialogue_line(int n,int topic){if(n>=32&&n<=35&&topic==0){const char*line[]={"Мы ромская семья, недавно поселились в районе. Я мастер по ремонту, сейчас после смены.","Работаю в поликлинике. Зимой главное — тепло одеваться и вовремя отдыхать.","Днём работаю на доставке. Во дворе хорошо бы почистить дорожки.","Учусь и подрабатываю в ателье. Люблю, когда во дворе цветы, а не один асфальт."};SN(dialogue,sizeof(dialogue),"%s",line[n-32]);return dialogue;}const char*manner[]={"Сегодня со смены пораньше. Замёрз, домой бы.","На заводе опять задерживают зарплату.","В ларьке свежий хлеб привезли. Пока разбирают.","Дома батареи еле тёплые. Такая вот зима.","До автобуса ещё полчаса. Постою, с людьми поболтаю.","Сосед машину третий день заводит. Мороз давит.","После смены только чай да спать.","Во дворе спокойно. Все свои."};if(npc_child(n))SN(dialogue,sizeof(dialogue),"%s",topic==0?"Мы тут играем. Только далеко не уходим.":topic==1?"Мама сказала до темноты вернуться.":"У соседей кот есть. Можно погладить?");else if(topic==0)SN(dialogue,sizeof(dialogue),"%s",manner[persona(n)]);else if(topic==1){if(g.lifeHunger[n]<30)SN(dialogue,sizeof(dialogue),"%s",g.lifeWallet[n]<20?"Проголодался. Денег на магазин мало, домой схожу.":"Проголодался. Зайду за едой в магазин.");else if(g.lifeEnergy[n]<20)SN(dialogue,sizeof(dialogue),"%s","Сил совсем нет. Домой, отдохнуть.");else SN(dialogue,sizeof(dialogue),"Сейчас: %s. Потом видно будет.",activity_name(PERSON(n).activity));}else SN(dialogue,sizeof(dialogue),"%s",manner[(persona(n)+3)%8]);return dialogue;}
static void event_log(const char*kind,int id){char b[240];int len=SN(b,sizeof(b),"%s,%d,%.5f,%.3f,%u,%.4f\n",kind,id,g.absolute,realTime,g.worldSeed,eventValue);FILE*f=fopen(eventpath,"ab");if(f){if(len>0&&len<(int)sizeof(b))fwrite(b,1,len,f);fclose(f);}eventsWritten++;lastWindowEvent=id;eventValue=0;}
static void focus_profile(int on){g.focusMode=on;g.uiMotion=on?0:2;g.popupMode=!on;g.highContrast=on;hudMode=on?1:0;showRadar=!on;showHints=1;headbob=0;g.hudOpacity=1;}
static float catVoiceCooldown=0;static int catMeowCount=0;
static void extended_defaults(int old){catVoiceCooldown=0;catMeowCount=0;if(old){g.winter=1;g.focusMode=0;g.uiMotion=1;g.popupMode=0;g.highContrast=0;g.fastMode=0;g.hudOpacity=1;g.mapSize=1;g.mapOpacity=.94f;g.mapZoom=1;g.lootMask=0;g.catBond=20;}g.hudOpacity=clamp(g.hudOpacity,0,1);g.mapSize=clamp(g.mapSize,.75f,1.2f);g.mapOpacity=clamp(g.mapOpacity,.1f,1);g.mapZoom=clamp(g.mapZoom,1,3);g.uiMotion=(int)clamp(g.uiMotion,0,2);winterEnabled=!!g.winter;seated=-1;navHouse=-1;catX=hx[0]+1.4f;catZ=hz[0]-1;catTX=catX;catTZ=catZ;catTimer=2;catState=0;for(int n=0;n<NN;n++)chatUntil[n]=0;}
static void cat_tick(float dt){
 catVoiceCooldown=mx(0,catVoiceCooldown-dt);if(g.petHunger<35&&catState!=4&&catVoiceCooldown<=0){float d=dst(g.x,g.z,catX,catZ);if(soundEnabled&&d<15&&g.playerY<2.8f){audio(7);Voice*v=&voices[(voiceNext-1)%8];v->gain=clamp(1-d/16,.05f,1)*(insideHouse==0?1:.15f);catMeowCount++;}catVoiceCooldown=9+(float)((int)realTime%7);if(g.petHunger<20){catTX=hx[0]+1.4f;catTZ=hz[0]-1.3f;catState=1;}}
 /* Home-local simulation. Never references player movement as a destination. */
 catTimer-=dt;
 if(catState==3||catState==4){if(catTimer<=0){catState=1;catTX=hx[0]+1.4f;catTZ=hz[0]-1;catTimer=5;}}
 else if(catTimer<=0){catState=catState==0?1:0;catTimer=4+rnd()*7;if(catState==1){catTX=hx[0]+.4f+rnd()*2;catTZ=hz[0]-1.5f+rnd()*1.5f;}}
 float d=dst(catX,catZ,catTX,catTZ);if(catState==1&&d>.03f){float step=mn(d,dt*.55f);catX+=(catTX-catX)*step/d;catZ+=(catTZ-catZ)*step/d;catPhase+=step*9;}
 catX=clamp(catX,hx[0]+.35f,hx[0]+2.45f);catZ=clamp(catZ,hz[0]-1.55f,hz[0]+.1f);
}
